528  static bool parse_headers(struct lwan_request_parser_helper *helper,
   529                            char *buffer)
   530  {
   531      char *buffer_end = helper->buffer->value + helper->buffer->len;
   532      char **header_start = helper->header_start;
   533      size_t n_headers = 0;
   534      char *p;
   535
   536      for (p = buffer + 1;;) {
   537          char *next_chr = p;
   538          char *next_hdr = memchr(next_chr, '\r', (size_t)(buffer_end - p));
   539
   540          if (!next_hdr)
   541              break;
   542
   543          if (next_chr == next_hdr) {
   544              if (buffer_end - next_chr > 2) {
   545                  STRING_SWITCH_SMALL (next_hdr) {
   546                  case MULTICHAR_CONSTANT_SMALL('\r', '\n'):
   547                      helper->next_request = next_hdr + 2;
   548                  }
   549              }
   550              break;
   551          }
   552
   553          header_start[n_headers++] = next_chr;
   554          header_start[n_headers++] = next_hdr;
   555
   556          p = next_hdr + 2;
   557
   558          if (n_headers > N_HEADER_START || p >= buffer_end) {
   559              helper->n_header_start = 0;
   560              return false;
   561          }
   562      }
   563
   564      for (size_t i = 0; i < n_headers; i += 2) {
   565          char *end = header_start[i + 1];
   566
   567          p = header_start[i];
   568
   569          STRING_SWITCH_L (p) {
   570          case MULTICHAR_CONSTANT_L('A', 'c', 'c', 'e'):
   571              p += HEADER_LENGTH("Accept");
   572
   573              STRING_SWITCH_L (p) {
   574              case MULTICHAR_CONSTANT_L('-', 'E', 'n', 'c'):
   575                  helper->accept_encoding = HEADER("-Encoding");
   576                  break;
   577              }
   578              break;
   579          case MULTICHAR_CONSTANT_L('A', 'u', 't', 'h'):
   580              helper->authorization = HEADER("Authorization");
   581              break;
   582          case MULTICHAR_CONSTANT_L('C', 'o', 'n', 'n'):
   583              helper->connection = HEADER("Connection");
   584              break;
   585          case MULTICHAR_CONSTANT_L('C', 'o', 'n', 't'):
   586              p += HEADER_LENGTH("Content");
   587
   588              STRING_SWITCH_L (p) {
   589              case MULTICHAR_CONSTANT_L('-', 'T', 'y', 'p'):
   590                  helper->content_type = HEADER("-Type");
   591                  break;
   592              case MULTICHAR_CONSTANT_L('-', 'L', 'e', 'n'):
   593                  helper->content_length = HEADER("-Length");
   594                  break;
   595              }
   596              break;
   597          case MULTICHAR_CONSTANT_L('C', 'o', 'o', 'k'):
   598              helper->cookie = HEADER("Cookie");
   599              break;
   600          case MULTICHAR_CONSTANT_L('I', 'f', '-', 'M'):
   601              helper->if_modified_since.raw = HEADER("If-Modified-Since");
   602              break;
   603          case MULTICHAR_CONSTANT_L('R', 'a', 'n', 'g'):
   604              helper->range.raw = HEADER("Range");
   605              break;
   606          }
   607      }
   608
   609      helper->n_header_start = n_headers;
   610      return true;
   611  }
