  1191  static enum lwan_http_status parse_http_request(struct lwan_request *request)
  1192  {
  1193      struct lwan_request_parser_helper *helper = request->helper;
  1194      char *buffer = helper->buffer->value;
  1195
  1196      if (request->flags & REQUEST_ALLOW_PROXY_REQS) {
  1197          /* REQUEST_ALLOW_PROXY_REQS will be cleared in lwan_process_request() */
  1198
  1199          buffer = parse_proxy_protocol(request, buffer);
  1200          if (UNLIKELY(!buffer))
  1201              return HTTP_BAD_REQUEST;
  1202      }
  1203
  1204      buffer = ignore_leading_whitespace(buffer);
  1205
  1206      char *path = identify_http_method(request, buffer);
  1207      if (UNLIKELY(!path))
  1208          return HTTP_NOT_ALLOWED;
  1209
  1210      buffer = identify_http_path(request, path);
  1211      if (UNLIKELY(!buffer))
  1212          return HTTP_BAD_REQUEST;
  1213
  1214      if (UNLIKELY(!parse_headers(helper, buffer)))
  1215          return HTTP_BAD_REQUEST;
  1216
  1217      ssize_t decoded_len = url_decode(request->url.value);
  1218      if (UNLIKELY(decoded_len < 0))
  1219          return HTTP_BAD_REQUEST;
  1220      request->original_url.len = request->url.len = (size_t)decoded_len;
  1221
  1222      parse_connection_header(request);
  1223
  1224      return HTTP_OK;
  1225  }
