  1648  __attribute__((used)) int fuzz_parse_http_request(const uint8_t *data,
  1649                                                    size_t length)
  1650  {
  1651      static struct coro_switcher switcher;
  1652      static struct coro *coro;
  1653      static char *header_start[N_HEADER_START];
  1654      static char data_copy[32767] = {0};
  1655
  1656      if (length > sizeof(data_copy))
  1657          length = sizeof(data_copy);
  1658      memcpy(data_copy, data, length);
  1659
  1660      if (!coro)
  1661          coro = coro_new(&switcher, useless_coro_for_fuzzing, NULL);
  1662
  1663      struct lwan_request_parser_helper helper = {
  1664          .buffer = &(struct lwan_value){.value = data_copy, .len = length},
  1665          .header_start = header_start,
  1666          .error_when_n_packets = 2,
  1667      };
  1668      struct lwan_connection conn = {.coro = coro};
  1669      struct lwan_proxy proxy = {};
  1670      struct lwan_request request = {
  1671          .helper = &helper,
  1672          .conn = &conn,
  1673          .flags = REQUEST_ALLOW_PROXY_REQS,
  1674          .proxy = &proxy,
  1675      };
  1676
  1677      /* If the finalizer isn't happy with a request, there's no point in
  1678       * going any further with parsing it. */
  1679      if (read_request_finalizer(length, sizeof(data_copy), &request, 1) !=
  1680          FINALIZER_DONE)
  1681          return 0;
  1682
  1683      if (parse_http_request(&request) == HTTP_OK) {
  1684          size_t gen = coro_deferred_get_generation(coro);
  1685
  1686          /* Only pointers were set in helper struct; actually parse them here. */
  1687          parse_post_data(&request);
  1688          parse_query_string(&request);
  1689          parse_cookies(&request);
  1690          parse_accept_encoding(&request);
  1691          parse_if_modified_since(&helper);
  1692          parse_range(&helper);
  1693
  1694          coro_deferred_run(coro, gen);
  1695      }
  1696
  1697      return 0;
  1698  }
